"""Fusion 360 script: chip chip1_triculture_dissociation_quench_cell_wash_filter (59 x 49 mm), generated by autochip/cad.py from chips/chip1_triculture_dissociation_quench_cell_wash_filter.json.
Run it in Fusion: Utilities > Scripts and Add-Ins, or send it through the Fusion MCP execute_code tool
(then set PARTS_DIR first). It
  1. imports every placed part (parts/<module>.stl, mm, chip origin) as its own component,
  2. sketches the board outline, the port circles and every channel centreline ("channel paths"),
  3. sketches every channel as a closed outline at its true width ("channel outlines"), ready to
     extrude-cut 0.3 mm into the fluidic layer (top of the fluidic layer at z = 1.5 mm).
Fusion's API works in cm; the numbers below are mm and converted on the way in.
"""
import adsk.core, adsk.fusion
import os

try:
    PARTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "parts")
except NameError:
    PARTS_DIR = globals()["PARTS_DIR"]
BOARD = [59.0, 49.0]
PARTS = [["split_1", "splitter"], ["culture_neurons", "culture_chamber_param"], ["culture_microglia", "culture_chamber_param"], ["culture_astrocytes", "culture_chamber_param"], ["junction_mid", "pool"], ["quench_join", "merge"], ["quench_mix", "mixer"], ["cell_wash", "spiral_separator"], ["cell_filter", "pillar_filter"]]
CHANNELS = [["ch_inlet_1_split_1", 0.2, [[2.5, 24.5], [4.3, 24.5]]], ["ch_junction_mid_quench_join", 0.3, [[30.3, 24.5], [31.9, 24.5]]], ["ch_quench_join_quench_mix", 0.3, [[33.7, 24.5], [35.3, 24.5]]], ["ch_quench_mix_cell_wash", 0.3, [[37.9, 24.5], [38.9, 24.5]]], ["ch_cell_wash_cell_filter", 0.3, [[51.7, 24.5], [52.7, 24.5]]], ["ch_cell_filter_outlet_1", 0.3, [[54.7, 24.5], [56.5, 24.5]]], ["ch_split_1_culture_neurons", 0.2, [[6.3, 39.3], [7.3, 39.3]]], ["ch_split_1_culture_microglia", 0.2, [[6.3, 24.5], [7.3, 24.5]]], ["ch_split_1_culture_astrocytes", 0.2, [[6.3, 9.7], [7.3, 9.7]]], ["ch_culture_neurons_junction_mid", 0.3, [[27.3, 39.3], [28.3, 39.3]]], ["ch_culture_microglia_junction_mid", 0.3, [[27.3, 24.5], [28.3, 24.5]]], ["ch_culture_astrocytes_junction_mid", 0.3, [[27.3, 9.7], [28.3, 9.7]]], ["ch_culture_medium_neurons_in_culture_neurons", 0.2, [[17.3, 45.2], [17.3, 44.3]]], ["ch_culture_neurons_culture_neurons_vent_out", 0.2, [[17.3, 34.3], [17.3, 33.4]]], ["ch_culture_medium_microglia_in_culture_microglia", 0.2, [[17.3, 30.4], [17.3, 29.5]]], ["ch_culture_microglia_microglia_vent_out", 0.2, [[15.8, 19.5], [15.8, 18.6]]], ["ch_culture_microglia_culture_microglia_vent_out", 0.2, [[18.8, 19.5], [18.8, 18.6]]], ["ch_culture_medium_astrocytes_in_culture_astrocytes", 0.2, [[17.3, 15.6], [17.3, 14.7]]], ["ch_culture_astrocytes_astrocytes_vent_out", 0.2, [[15.8, 4.7], [15.8, 3.8]]], ["ch_culture_astrocytes_culture_astrocytes_vent_out", 0.2, [[18.8, 4.7], [18.8, 3.8]]], ["ch_quench_solution_in_quench_join", 0.2, [[32.8, 46.5], [32.8, 25.4]]], ["ch_wash_buffer_in_cell_wash", 0.2, [[45.3, 46.5], [45.3, 30.9]]], ["ch_cell_wash_cell_wash_waste_out", 0.2, [[45.3, 18.1], [45.3, 2.5]]]]
OUTLINES = [["ch_inlet_1_split_1", [[2.5, 24.6], [4.3, 24.6], [4.3, 24.4], [2.5, 24.4]]], ["ch_junction_mid_quench_join", [[30.3, 24.65], [31.9, 24.65], [31.9, 24.35], [30.3, 24.35]]], ["ch_quench_join_quench_mix", [[33.7, 24.65], [35.3, 24.65], [35.3, 24.35], [33.7, 24.35]]], ["ch_quench_mix_cell_wash", [[37.9, 24.65], [38.9, 24.65], [38.9, 24.35], [37.9, 24.35]]], ["ch_cell_wash_cell_filter", [[51.7, 24.65], [52.7, 24.65], [52.7, 24.35], [51.7, 24.35]]], ["ch_cell_filter_outlet_1", [[54.7, 24.65], [56.5, 24.65], [56.5, 24.35], [54.7, 24.35]]], ["ch_split_1_culture_neurons", [[6.3, 39.4], [7.3, 39.4], [7.3, 39.2], [6.3, 39.2]]], ["ch_split_1_culture_microglia", [[6.3, 24.6], [7.3, 24.6], [7.3, 24.4], [6.3, 24.4]]], ["ch_split_1_culture_astrocytes", [[6.3, 9.8], [7.3, 9.8], [7.3, 9.6], [6.3, 9.6]]], ["ch_culture_neurons_junction_mid", [[27.3, 39.45], [28.3, 39.45], [28.3, 39.15], [27.3, 39.15]]], ["ch_culture_microglia_junction_mid", [[27.3, 24.65], [28.3, 24.65], [28.3, 24.35], [27.3, 24.35]]], ["ch_culture_astrocytes_junction_mid", [[27.3, 9.85], [28.3, 9.85], [28.3, 9.55], [27.3, 9.55]]], ["ch_culture_medium_neurons_in_culture_neurons", [[17.4, 45.2], [17.4, 44.3], [17.2, 44.3], [17.2, 45.2]]], ["ch_culture_neurons_culture_neurons_vent_out", [[17.4, 34.3], [17.4, 33.4], [17.2, 33.4], [17.2, 34.3]]], ["ch_culture_medium_microglia_in_culture_microglia", [[17.4, 30.4], [17.4, 29.5], [17.2, 29.5], [17.2, 30.4]]], ["ch_culture_microglia_microglia_vent_out", [[15.9, 19.5], [15.9, 18.6], [15.7, 18.6], [15.7, 19.5]]], ["ch_culture_microglia_culture_microglia_vent_out", [[18.9, 19.5], [18.9, 18.6], [18.7, 18.6], [18.7, 19.5]]], ["ch_culture_medium_astrocytes_in_culture_astrocytes", [[17.4, 15.6], [17.4, 14.7], [17.2, 14.7], [17.2, 15.6]]], ["ch_culture_astrocytes_astrocytes_vent_out", [[15.9, 4.7], [15.9, 3.8], [15.7, 3.8], [15.7, 4.7]]], ["ch_culture_astrocytes_culture_astrocytes_vent_out", [[18.9, 4.7], [18.9, 3.8], [18.7, 3.8], [18.7, 4.7]]], ["ch_quench_solution_in_quench_join", [[32.9, 46.5], [32.9, 25.4], [32.7, 25.4], [32.7, 46.5]]], ["ch_wash_buffer_in_cell_wash", [[45.4, 46.5], [45.4, 30.9], [45.2, 30.9], [45.2, 46.5]]], ["ch_cell_wash_cell_wash_waste_out", [[45.4, 18.1], [45.4, 2.5], [45.2, 2.5], [45.2, 18.1]]]]
PORTS = [["inlet_1", 2.5, 24.5, 1.0], ["outlet_1", 56.5, 24.5, 1.0], ["culture_medium_neurons_in", 17.3, 45.2, 1.0], ["culture_neurons_vent_out", 17.3, 33.4, 1.0], ["culture_medium_microglia_in", 17.3, 30.4, 1.0], ["microglia_vent_out", 15.8, 18.6, 1.0], ["culture_microglia_vent_out", 18.8, 18.6, 1.0], ["culture_medium_astrocytes_in", 17.3, 15.6, 1.0], ["astrocytes_vent_out", 15.8, 3.8, 1.0], ["culture_astrocytes_vent_out", 18.8, 3.8, 1.0], ["quench_solution_in", 32.8, 46.5, 1.0], ["wash_buffer_in", 45.3, 46.5, 1.0], ["cell_wash_waste_out", 45.3, 2.5, 1.0]]


def P(xy, z=0.0):
    return adsk.core.Point3D.create(xy[0] / 10.0, xy[1] / 10.0, z / 10.0)


def run(context=None):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    root = design.rootComponent
    for module_id, part in PARTS:
        occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
        comp = occ.component
        comp.name = module_id + " (" + part + ")"
        path = os.path.join(PARTS_DIR, module_id + ".stl")
        if design.designType == adsk.fusion.DesignTypes.ParametricDesignType:
            base = comp.features.baseFeatures.add()
            base.startEdit()
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit, base)
            base.finishEdit()
        else:
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit)
    sk = root.sketches.add(root.xYConstructionPlane)
    sk.name = "chip1_triculture_dissociation_quench_cell_wash_filter outline + ports + channel paths"
    lines = sk.sketchCurves.sketchLines
    lines.addTwoPointRectangle(P((0, 0)), P(BOARD))
    for pid, x, y, d in PORTS:
        sk.sketchCurves.sketchCircles.addByCenterRadius(P((x, y)), d / 20.0)
    for cid, width, pts in CHANNELS:
        for a, b in zip(pts[:-1], pts[1:]):
            lines.addByTwoPoints(P(a), P(b))
    sk2 = root.sketches.add(root.xYConstructionPlane)
    sk2.name = "chip1_triculture_dissociation_quench_cell_wash_filter channel outlines (true width)"
    for cid, pts in OUTLINES:
        for a, b in zip(pts, pts[1:] + pts[:1]):
            sk2.sketchCurves.sketchLines.addByTwoPoints(P(a), P(b))
    app.activeViewport.fit()
    return "imported %d parts, sketched %d channels and %d ports" % (len(PARTS), len(CHANNELS), len(PORTS))
